def judge(passwd):
    plen = 0
    if len(passwd) >= 8:
        plen = 1
    pnum, pupper, plower = False, False, False
    for ch in passwd:
        if ch in '0123456789':
            pnum = True
        if 'A' <= ch <= 'Z':
            pupper = True
        if 'a' <= ch <= 'z':
            plower = True
    result = plen + pnum + pupper + plower
    return result

while True:
    pw = input()
    if pw == '':
        break
    s = judge(pw)
    if s <= 2:
        print('弱密码')
    elif s == 3:
        print('中等密码')
    else:
        print('强密码')
